type CurrentlyPlaying struct {
	ID         string      `json:"id"`
	Timestamp  int         `json:"timestamp"`
	ProgressMS int         `json:"progress_ms"`
	Item       TrackObject `json:"item"`
}

type TrackObject struct {
	Album Album `json:"album"`
}

